        if (!ctx) {           reject(new Error("unsupported_or_corrupt_image"));           return;         }         ctx.drawImage(img, 0, 0, sampleSize, sampleSize);         const {           data         } = ctx.getImageData(0, 0, sampleSize, sampleSize);         const lumGrid = new Float32Array(sampleSize * sampleSize);         let sumLum = 0;         let sumSqLum = 0;
